  /**
   * @method
   * @name modetrade#fetchStatus
   * @description the latest known information on the availability of the
   * exchange API
   * @see
   * https://orderly.network/docs/build-on-evm/evm-api/restful-api/public/get-system-maintenance-status
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [status structure]{@link
   * https://docs.ccxt.com/?id=exchange-status-structure}
   */
  std::shared_future<std::any>
  fetchStatus(std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        std::any response = awaitValue(
                            this->v1PublicGetPublicSystemInfo(params));
                        //
                        //     {
                        //         "success": true,
                        //         "data": {
                        //             "status": 0,
                        //             "msg": "System is functioning properly."
                        //         },
                        //         "timestamp": "1709274106602"
                        //     }
                        //
                        std::any data = this->safeDict(
                            response, std::string("data"), ccxt::dict{});
                        std::any status =
                            this->safeString(data, std::string("status"));
                        if (isTrue(isEqual(status, std::any{}))) {
                          status = std::string("error");
                        } else if (isTrue(isEqual(status, std::string("0")))) {
                          status = std::string("ok");
                        } else {
                          status = std::string("maintenance");
                        }
                        return ccxt::dict{
                            {std::string("status"), status},
                            {std::string("updated"), std::any{}},
                            {std::string("eta"), std::any{}},
                            {std::string("url"), std::any{}},
                            {std::string("info"), response},
                        };
                      })
        .share();
  }

  /**
   * @method
   * @name modetrade#fetchTime
   * @description fetches the current integer timestamp in milliseconds from the
   * exchange server
   * @see
   * https://orderly.network/docs/build-on-evm/evm-api/restful-api/public/get-system-maintenance-status
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {int} the current integer timestamp in milliseconds from the
   * exchange server
   */
  std::shared_future<std::any>
  fetchTime(std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any response =
                     awaitValue(this->v1PublicGetPublicSystemInfo(params));
                 //
                 //     {
                 //         "success": true,
                 //         "data": {
                 //             "status": 0,
                 //             "msg": "System is functioning properly."
                 //         },
                 //         "timestamp": "1709274106602"
                 //     }
                 //
                 return this->safeInteger(response, std::string("timestamp"));
               })
        .share();
  }

  std::any parseMarket(std::any market) override {
    //
    //   {
    //     "symbol": "PERP_BTC_USDC",
    //     "quote_min": 123,
    //     "quote_max": 100000,
    //     "quote_tick": 0.1,
    //     "base_min": 0.00001,
    //     "base_max": 20,
    //     "base_tick": 0.00001,
    //     "min_notional": 1,
    //     "price_range": 0.02,
    //     "price_scope": 0.4,
    //     "std_liquidation_fee": 0.03,
    //     "liquidator_fee": 0.015,
    //     "claim_insurance_fund_discount": 0.0075,
    //     "funding_period": 8,
    //     "cap_funding": 0.000375,
    //     "floor_funding": -0.000375,
    //     "interest_rate": 0.0001,
    //     "created_time": 1684140107326,
    //     "updated_time": 1685345968053,
    //     "base_mmr": 0.05,
    //     "base_imr": 0.1,
    //     "imr_factor": 0.0002512,
    //     "liquidation_tier": "1"
    //   }
    //
    std::any marketId =
        this->safeString(market, std::string("symbol"), std::string(""));
    std::any parts = split(marketId, std::string("_"));
    std::any marketType = std::string("swap");
    std::any baseId = this->safeString(parts, 1);
    std::any quoteId = this->safeString(parts, 2);
    std::any base = this->safeCurrencyCode(baseId);
    std::any quote = this->safeCurrencyCode(quoteId);
    std::any settleId = this->safeString(parts, 2);
    std::any settle = this->safeCurrencyCode(settleId);
    std::any symbol = add(
        add(add(add(base, std::string("/")), quote), std::string(":")), settle);
    return this->safeMarketStructure(ccxt::dict{
        {std::string("id"), marketId},
        {std::string("symbol"), symbol},
        {std::string("base"), base},
        {std::string("quote"), quote},
        {std::string("settle"), settle},
        {std::string("baseId"), baseId},
        {std::string("quoteId"), quoteId},
        {std::string("settleId"), settleId},
        {std::string("type"), marketType},
        {std::string("spot"), false},
        {std::string("margin"), false},
        {std::string("swap"), true},
        {std::string("future"), false},
        {std::string("option"), false},
        {std::string("active"), std::any{}},
        {std::string("contract"), true},
        {std::string("linear"), true},
        {std::string("inverse"), false},
        {std::string("contractSize"), this->parseNumber(std::string("1"))},
        {std::string("expiry"), std::any{}},
        {std::string("expiryDatetime"), std::any{}},
        {std::string("strike"), std::any{}},
        {std::string("optionType"), std::any{}},
        {std::string("precision"),
         ccxt::dict{
             {std::string("amount"),
              this->safeNumber(market, std::string("base_tick"))},
             {std::string("price"),
              this->safeNumber(market, std::string("quote_tick"))},
         }},
        {std::string("limits"),
         ccxt::dict{
             {std::string("leverage"),
              ccxt::dict{
                  {std::string("min"), std::any{}},
                  {std::string("max"), std::any{}},
              }},
             {std::string("amount"),
              ccxt::dict{
                  {std::string("min"),
                   this->safeNumber(market, std::string("base_min"))},
                  {std::string("max"),
                   this->safeNumber(market, std::string("base_max"))},
              }},
             {std::string("price"),
              ccxt::dict{
                  {std::string("min"),
                   this->safeNumber(market, std::string("quote_min"))},
                  {std::string("max"),
                   this->safeNumber(market, std::string("quote_max"))},
              }},
             {std::string("cost"),
              ccxt::dict{
                  {std::string("min"),
                   this->safeNumber(market, std::string("min_notional"))},
                  {std::string("max"), std::any{}},
              }},
         }},
        {std::string("created"),
         this->safeInteger(market, std::string("created_time"))},
        {std::string("info"), market},
    });
  }

