  /**
   * @method
   * @name modetrade#fetchClosedOrders
   * @description fetches information on multiple orders made by the user
   * @see
   * https://orderly.network/docs/build-on-evm/evm-api/restful-api/private/get-orders
   * @see
   * https://orderly.network/docs/build-on-evm/evm-api/restful-api/private/get-algo-orders
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.trigger] whether the order is a stop/algo order
   * @param {boolean} [params.is_triggered] whether the order has been triggered
   * (false by default)
   * @param {string} [params.side] 'buy' or 'sell'
   * @param {int} params.until timestamp in ms of the latest order to fetch
   * @param {boolean} [params.paginate] set to true if you want to fetch orders
   * with pagination
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchClosedOrders(std::any symbol = std::any{}, std::any since = std::any{},
                    std::any limit = std::any{},
                    std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any extendedParams =
                            this->extend(params, ccxt::dict{
                                                     {std::string("status"),
                                                      std::string("COMPLETED")},
                                                 });
                        return awaitValue(this->fetchOrders(
                            symbol, since, limit, extendedParams));
                      })
        .share();
  }

